import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class LittleCLoves3II {
    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    static class Solver {
        long solve(long n, long m) {
            if (n > m) {
                long tmp = n;
                n = m;
                m = tmp;
            }

            if (n == 1) {
                return m / 6 * 6 + Math.max(m % 6 - 3, 0) * 2;
            }

            if (n == 2) {
                switch ((int) m) {
                    case 2:
                        return 0;
                    case 3:
                        return 4;
                    case 7:
                        return 12;
                    default:
                        return n * m;
                }
            }

            return n * m / 2 * 2;
        }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);
        out.println(new Solver().solve(in.nextInt(), in.nextInt()));
        out.close();
    }
}
